import java.util.Stack;

public class Program {
    public static void main(String[] args) {
        Stack<String> stack = new Stack<>();
        stack.push("Java");
        stack.push("Python");
        System.out.println(stack);
    }
}

Stack<String> stack = new Stack<>();
stack.push("A");
stack.push("B");
System.out.println(stack);

Stack<String> stack = new Stack<>();
stack.push("A");
stack.push("B");
System.out.println(stack.pop());

Stack<String> stack = new Stack<>();
stack.push("A");
stack.push("B");
System.out.println(stack.peek());
